import{c as s,$ as l,Q as c,j as d,g as t,o as u,n as a,m as o,a4 as n}from"./chunks/framework.Ce_49mA8.js";const v=JSON.parse('{"title":"Ambassador Module","description":"Practical guide to the Ambassador cross-cutting module: business promotion, smart link generation, digital receipt QR codes, campaign CRM, and partner affiliate ecosystem.","frontmatter":{"title":"Ambassador Module","description":"Practical guide to the Ambassador cross-cutting module: business promotion, smart link generation, digital receipt QR codes, campaign CRM, and partner affiliate ecosystem.","datePublished":"2026-10-28","dateModified":"2026-11-16","order":22},"headers":[],"relativePath":"docs/spaces/ambassador.md","filePath":"docs/spaces/ambassador.md","lastUpdated":1794787200000}'),p={name:"docs/spaces/ambassador.md"},h={id:"ambassador-module-business-promotion-and-partner-ecosystem",tabindex:"-1"};function g(i,e,m,f,y,b){const r=l("DocIcon");return c(),d("div",null,[t("h1",h,[u(r,{name:"ambassador"}),e[0]||(e[0]=a(" Ambassador Module: Business Promotion and Partner Ecosystem ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#ambassador-module-business-promotion-and-partner-ecosystem","aria-label":'Permalink to "Ambassador Module: Business Promotion and Partner Ecosystem"'},"​",-1))]),e[5]||(e[5]=o('<p>Every craftsman crafting quality goods or delivering dependable repair services eventually faces the challenge of customer acquisition. Some publish masterclasses and tips on specialized forums, others build social media communities, while others invest in paid advertising or collaborate with fellow artisans.</p><p>In most small business applications, marketing workflows are either completely omitted or outsourced to complex, expensive external software. In OmniCraft ERP, this capability is provided as a complimentary built-in extension — <strong>the Ambassador module</strong>.</p><p>The tool solves two critical objectives for working entrepreneurs:</p><ul><li><strong>Promoting Your Own Workshop:</strong> systematic discovery of promotional channels, advertising campaign management, deterministic tracking link generation, AI-assisted content drafting, and transparent return-on-investment analytics;</li><li><strong>Affiliate Revenue in the OmniCraft ERP Ecosystem:</strong> introducing the platform to fellow artisans while earning lifetime commissions (up to 50% on every payment from referred users), with flexible payouts to bank accounts or direct license redemptions.</li></ul><hr><h2 id="tool-architecture-dual-mode-operation-and-data-isolation" tabindex="-1">Tool Architecture: Dual-Mode Operation and Data Isolation <a class="header-anchor" href="#tool-architecture-dual-mode-operation-and-data-isolation" aria-label="Permalink to &quot;Tool Architecture: Dual-Mode Operation and Data Isolation&quot;">​</a></h2><p>The module is engineered for complete operational autonomy and minimal computer resource footprint:</p><div class="craft-window-frame" data-title="Ambassador Module — Navigation Bar"><table class="craft-matrix-table" style="margin:0;text-align:center;"><thead><tr><th style="width:20%;text-align:center;">Cabinet</th><th style="width:20%;text-align:center;">Sources</th><th style="width:20%;text-align:center;">Campaigns</th><th style="width:20%;text-align:center;">Analytics</th><th style="width:20%;text-align:center;">Settings</th></tr></thead><tbody><tr><td style="text-align:center;">Partner Profile &amp; Links</td><td style="text-align:center;">Channel Directory &amp; AI</td><td style="text-align:center;">Active Campaigns &amp; Copy</td><td style="text-align:center;">Funnels &amp; ROI Reports</td><td style="text-align:center;">Automation &amp; API</td></tr></tbody></table></div><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"></rect><path d="M3 9h18"></path><path d="M9 21V9"></path></svg></span><span><strong>Dual-Mode Execution:</strong> the module operates as an integrated screen within the primary OmniCraft ERP workspace (matching the unified command bar aesthetic of &quot;My Capital&quot;), and can also be launched as a standalone executable <code>Ambassador.exe</code>.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg></span><span><strong>Global Data Preservation:</strong> all generated links, channel records, draft publications, and metrics are stored in a dedicated secure database file <code>global_extensions.db</code>. If you reconfigure your workshop, purge test cash registers, or archive a production workspace, the module&#39;s records remain untouched.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg></span><span><strong>Network Disconnection Resilience:</strong> link creation, directory updates, and local metric evaluations operate 100% offline. During temporary internet drops, the system instantly serves cached data without application freezes.</span></li></ul><div class="tip custom-block"><p class="custom-block-title">Direct Access via Menu</p><p>Access the module at any time via the main application drawer or the &quot;Cross-Cutting Modules&quot; sidebar group. The tool is available free of charge across all commercial licenses.</p></div><hr><h2 id="_1-cabinet-tab-personal-profile-quick-links-and-links-directory" tabindex="-1">1. &quot;Cabinet&quot; Tab: Personal Profile, Quick Links, and Links Directory <a class="header-anchor" href="#_1-cabinet-tab-personal-profile-quick-links-and-links-directory" aria-label="Permalink to &quot;1. &quot;Cabinet&quot; Tab: Personal Profile, Quick Links, and Links Directory&quot;">​</a></h2><p>The <strong>&quot;Cabinet&quot;</strong> tab serves as the command center for your promotional initiatives and tracks performance metrics.</p><div class="craft-window-frame" data-title="Partner Profile &amp; Performance Summary"><div style="padding:16px 20px;border-bottom:1px solid var(--vp-c-divider);"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><span><strong>Partner Tier:</strong> Master (30% Commission)</span><span style="font-size:0.85em;color:var(--vp-c-text-2);">Next Tier: Legend (24/50 sales)</span></div><div class="breakdown-bar-track" style="height:8px;background:var(--vp-c-bg-soft);border-radius:4px;overflow:hidden;display:flex;"><div class="breakdown-segment" style="width:48%;background:#10b981;" title="Progress to Legend"></div><div class="breakdown-segment" style="width:52%;background:rgba(16, 185, 129, 0.15);" title="Remaining Sales"></div></div></div><table class="craft-matrix-table" style="margin:0;text-align:center;"><thead><tr><th style="width:33%;text-align:center;">Link Clicks</th><th style="width:33%;text-align:center;">Completed Sales</th><th style="width:34%;text-align:center;">Available Balance</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1,420</strong></td><td style="text-align:center;"><strong>24</strong></td><td style="text-align:center;"><strong style="color:#10b981;">$ 186.00</strong></td></tr></tbody></table></div><h3 id="personal-profile-and-milestone-rewards-ladder" tabindex="-1">Personal Profile and Milestone Rewards Ladder <a class="header-anchor" href="#personal-profile-and-milestone-rewards-ladder" aria-label="Permalink to &quot;Personal Profile and Milestone Rewards Ladder&quot;">​</a></h3><p>OmniCraft ERP recognizes the dedication of active craftsmen through a transparent three-tier milestone system:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Partner Tier</th><th style="text-align:center;">Commission Rate</th><th style="text-align:center;">Qualification Threshold</th><th style="text-align:left;">Tier Capabilities</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Partner</strong></td><td style="text-align:center;"><strong>20%</strong></td><td style="text-align:center;">Baseline level (0 sales)</td><td style="text-align:left;">Unlimited link generation, receipt QR codes, withdrawals from $ 15.00.</td></tr><tr><td style="text-align:left;"><strong>Master</strong></td><td style="text-align:center;"><strong>30%</strong></td><td style="text-align:center;">From 10 sales within rolling 30 days</td><td style="text-align:left;">Higher commission percentage, priority payout processing.</td></tr><tr><td style="text-align:left;"><strong>Legend</strong></td><td style="text-align:center;"><strong>50%</strong></td><td style="text-align:center;">From 50 sales within rolling 30 days</td><td style="text-align:left;">Maximum affiliate revenue share across all product subscriptions.</td></tr></tbody></table><p>Directly below the profile card sits the available balance tracker. Clicking the <strong>&quot;Redeem Bonus&quot;</strong> button opens a dialog window where you can:</p><ol><li>Request an affiliate earnings withdrawal to your bank accounts;</li><li>Apply accumulated bonuses to extend an active Standard subscription;</li><li>Unlock a perpetual upgrade to the PRO tier without spending out-of-pocket cash.</li></ol><h3 id="quick-link-generator" tabindex="-1">Quick Link Generator <a class="header-anchor" href="#quick-link-generator" aria-label="Permalink to &quot;Quick Link Generator&quot;">​</a></h3><p>When you need to send a targeted link to a colleague in direct messages or share a cost calculator in a discussion thread, there is no need to set up a comprehensive campaign.</p><p>The <strong>&quot;Quick Link&quot;</strong> generator requires only three straightforward inputs:</p><ul><li><strong>Link Name:</strong> a descriptive label for your records (e.g., <em>&quot;Leathercraft Discord Discussion&quot;</em>);</li><li><strong>Target Page:</strong> select the destination URL from the built-in catalog: <ul><li><em>Home Page</em> (<code>/</code>);</li><li><em>Product Cost Calculator</em> (<code>/calculator</code>);</li><li><em>Pricing &amp; Margins</em> (<code>/pricing</code>);</li><li><em>Software Overview</em> (<code>/software</code>);</li><li><em>Knowledge Base &amp; Blog</em> (<code>/blog</code>);</li><li><em>Interactive Web Demo</em> (<code>/demo</code>);</li><li><em>Custom Destination URL</em> (any valid URL on the official domain);</li></ul></li><li><strong>Campaign Tag and Notes:</strong> optional fields for enhanced bookkeeping.</li></ul><p>Click the blue <strong>&quot;Create Link&quot;</strong> button: the system normalizes the path, appends your unique referral code, and renders the finished URL ready for one-click clipboard copying.</p><h3 id="unified-links-center-directory" tabindex="-1">Unified Links Center (Directory) <a class="header-anchor" href="#unified-links-center-directory" aria-label="Permalink to &quot;Unified Links Center (Directory)&quot;">​</a></h3><p>Below the generator sits the master directory of all created links with intuitive filters:</p><ul><li><strong>&quot;All Links&quot;</strong> — master overview of every active tracking link;</li><li><strong>&quot;Quick Links&quot;</strong> — standalone links created for direct messaging;</li><li><strong>&quot;From Campaigns&quot;</strong> — links explicitly associated with promotional projects.</li></ul><p>Each entry provides four key interactions:</p><ol><li><strong>Copy:</strong> instant clipboard copying;</li><li><strong>QR Code Inspection:</strong> modal window displaying a high-contrast QR code optimized for smartphone scanning directly off desktop displays;</li><li><strong>Campaign Association:</strong> retroactively attach any standalone quick link to a campaign;</li><li><strong>Safe Removal:</strong> purge outdated links with explicit confirmation.</li></ol><h3 id="organic-growth-qr-codes-on-electronic-sales-receipts" tabindex="-1">Organic Growth: QR Codes on Electronic Sales Receipts <a class="header-anchor" href="#organic-growth-qr-codes-on-electronic-sales-receipts" aria-label="Permalink to &quot;Organic Growth: QR Codes on Electronic Sales Receipts&quot;">​</a></h3><p>One of the most effective organic channels is sharing software credentials directly with real customers of your workshop.</p><p>Enable the <strong>&quot;Place QR code on receipts&quot;</strong> toggle:</p><ul><li>When completing a retail order in the POS register, OmniCraft ERP automatically attaches a clean QR code badge to the bottom of digital receipts;</li><li>Customers scan the code from their mobile device, visit the site, and explore the system;</li><li>If the recipient ever licenses OmniCraft ERP for their own business, the billing server permanently binds the account to your partner profile.</li></ul><p>The right side of the card displays a live preview showing how the receipt badge renders on paper and mobile screens.</p><hr><h2 id="_2-sources-tab-ai-channel-discovery-and-verified-directory" tabindex="-1">2. &quot;Sources&quot; Tab: AI Channel Discovery and Verified Directory <a class="header-anchor" href="#_2-sources-tab-ai-channel-discovery-and-verified-directory" aria-label="Permalink to &quot;2. &quot;Sources&quot; Tab: AI Channel Discovery and Verified Directory&quot;">​</a></h2><p>Marketing yields meaningful results only when speaking to audiences who genuinely benefit from your craft. The <strong>&quot;Sources&quot;</strong> tab helps artisans discover and organize their communication channels.</p><div class="craft-window-frame" data-title="Channel Discovery and Verified Library"><table class="craft-matrix-table" style="margin:0;"><thead><tr><th style="width:55%;">AI Channel Strategist Chat</th><th style="width:45%;">Sources Library &amp; Candidates</th></tr></thead><tbody><tr><td><ul class="craft-feature-list" style="margin:0;"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg></span><div><strong>Discovery Query:</strong> &quot;Where to find bespoke leatherworkers?&quot;</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><line x1="9" y1="9" x2="15" y2="9"></line><line x1="9" y1="13" x2="15" y2="13"></line></svg></span><div><strong>Candidate Card:</strong> Custom Shoe Repair Forum.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><div><strong>Parameters:</strong> 12,000 members, 14-day posting cooldown.</div></li></ul></td><td><ul class="craft-feature-list" style="margin:0;"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle></svg></span><div><strong>Leathercraft Club:</strong> 3 campaigns (2 active).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg></span><div><strong>Woodworkers Chat:</strong> 1 active campaign.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polygon points="23 7 16 12 23 17 23 7"></polygon><rect x="1" y="5" width="15" height="14" rx="2" ry="2"></rect></svg></span><div><strong>Tool Restorers:</strong> Ready for launch (0 campaigns).</div></li></ul></td></tr></tbody></table></div><h3 id="conversational-ai-platform-discovery" tabindex="-1">Conversational AI Platform Discovery <a class="header-anchor" href="#conversational-ai-platform-discovery" aria-label="Permalink to &quot;Conversational AI Platform Discovery&quot;">​</a></h3><p>The built-in strategist operates on top of the centralized core artificial intelligence hub (<code>core.ai</code> using direct personal API access tokens).</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="m4.93 4.93 4.24 4.24"></path><path d="m14.83 9.17 4.24-4.24"></path><path d="m14.83 14.83 4.24 4.24"></path><path d="m9.17 14.83-4.24 4.24"></path></svg></span><span><strong>Tailored Inquiries for Craftsmen:</strong> submit queries in everyday language: <em>&quot;Where can I find bespoke leatherworkers to showcase our raw material cutting calculator?&quot;</em>.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline></svg></span><span><strong>Structured Channel Cards:</strong> the AI responds with detailed channel cards evaluating audience sizing, moderation rules, and recommended posting intervals.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 11 12 14 22 4"></polyline><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"></path></svg></span><span><strong>Batch Candidate Selection:</strong> click <strong>&quot;Select&quot;</strong> on relevant suggestions to collect them into the top tray, then save them all to your persistent directory with one click.</span></li></ul><h3 id="anatomy-of-a-channel-record" tabindex="-1">Anatomy of a Channel Record <a class="header-anchor" href="#anatomy-of-a-channel-record" aria-label="Permalink to &quot;Anatomy of a Channel Record&quot;">​</a></h3><p>Every promotional source is cataloged across six distinct classifications:</p><ul><li><strong>Community:</strong> social media groups, channels, and workshop chat groups;</li><li><strong>Article / Blog:</strong> guest editorial posts, craft industry portals, and publications;</li><li><strong>Forum:</strong> traditional discussion boards with threaded topics;</li><li><strong>Video:</strong> video hosting platforms, equipment reviews, and tutorial channels;</li><li><strong>Advertising:</strong> sponsored banners, search placements, and direct promotions;</li><li><strong>Other:</strong> trade fairs, craft exhibitions, and in-person meetups.</li></ul><p>Beyond type, each card tracks audience demographics, moderation policies (to protect against spam violations), preferred communication tone, and the <strong>cooldown interval</strong> between subsequent posts in days.</p><h3 id="user-managed-verified-channel-library-zero-hardcode" tabindex="-1">User-Managed Verified Channel Library (Zero-Hardcode) <a class="header-anchor" href="#user-managed-verified-channel-library-zero-hardcode" aria-label="Permalink to &quot;User-Managed Verified Channel Library (Zero-Hardcode)&quot;">​</a></h3><p>OmniCraft ERP includes no hardcoded promotional directories. The library is curated entirely by the craftsman:</p><ul><li>Any record can be edited, updated with administrator contacts, or archived;</li><li>The directory displays participation counts (e.g., <em>&quot;Leathercraft Club: 3 campaigns, 2 active&quot;</em>);</li><li>Complete functionality is available <strong>in fully manual mode</strong> — even without configuring external AI credentials, you can add channels using the standard <strong>&quot;Add Source&quot;</strong> button.</li></ul><hr><h2 id="_3-campaigns-tab-source-participations-content-and-publishing" tabindex="-1">3. &quot;Campaigns&quot; Tab: Source Participations, Content, and Publishing <a class="header-anchor" href="#_3-campaigns-tab-source-participations-content-and-publishing" aria-label="Permalink to &quot;3. &quot;Campaigns&quot; Tab: Source Participations, Content, and Publishing&quot;">​</a></h2><p>The <strong>&quot;Campaigns&quot;</strong> tab orchestrates every dimension of promotional workflows into an orderly process: from conceptualization to execution tracking.</p><div class="craft-window-frame" data-title="Campaign Management: &quot;Autumn Costing 2026&quot;"><table class="craft-matrix-table" style="margin:0;"><thead><tr><th style="width:55%;">Campaign Settings &amp; Creatives</th><th style="width:45%;">Channel Participations &amp; Tracking</th></tr></thead><tbody><tr><td><ul class="craft-feature-list" style="margin:0;"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path><path d="M2 12h20"></path></svg></span><div><strong>Landing Destination:</strong> <code>/calculator</code> (Tags: leather, costing).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><div><strong>Status &amp; Window:</strong> Active (due Nov 30, 2026).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg></span><div><strong>Publication Copy:</strong> Variant A (Forum), Variant B (Social Post).</div></li></ul></td><td><ul class="craft-feature-list" style="margin:0;"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Leathercraft Forum:</strong> Organic · [ Published ].</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg></span><div><strong>Tracking Link:</strong> <code>...?ref=INV-A1B2...</code></div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><div><strong>Next Step:</strong> Check initial clicks in 3 days.</div></li></ul></td></tr></tbody></table></div><h3 id="the-campaign-lifecycle" tabindex="-1">The Campaign Lifecycle <a class="header-anchor" href="#the-campaign-lifecycle" aria-label="Permalink to &quot;The Campaign Lifecycle&quot;">​</a></h3><p>Campaigns are created for concrete workshop milestones: showcasing a new custom toolset, publishing an apprenticeship curriculum, or launching a costing calculator.</p><p>The workflow follows five clear steps:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><span><strong>Step 1: Create Campaign.</strong> Click <strong>&quot;New Campaign&quot;</strong>, assign a clear title, select the landing page destination, configure execution dates, and add categorical tags for reporting.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><line x1="19" y1="8" x2="19" y2="14"></line><line x1="22" y1="11" x2="16" y2="11"></line></svg></span><span><strong>Step 2: Assign Channels.</strong> Connect verified sources from your library. For each placement, specify the mode (<em>&quot;Organic&quot;</em> or <em>&quot;Paid&quot;</em> with dedicated budget figures).</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg></span><span><strong>Step 3: Deterministic Link Generation.</strong> When a channel is attached, the system automatically builds an exact &quot;Campaign × Source&quot; pair with unique parameters. All links are generated by code, eliminating human formatting errors.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg></span><span><strong>Step 4: Draft Publication Copy.</strong> Compose copy tailored to the platform&#39;s format (forum technical response, community post, long-form editorial), or write copy manually.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Step 5: Publish and Track Progress.</strong> Place the material and update the status to <code>Published</code>. The system triggers the follow-up countdown.</span></li></ul><h3 id="participation-lifecycle-statuses" tabindex="-1">Participation Lifecycle Statuses <a class="header-anchor" href="#participation-lifecycle-statuses" aria-label="Permalink to &quot;Participation Lifecycle Statuses&quot;">​</a></h3><p>Each placement progresses across four distinct stages:</p><ul><li><code>Candidate</code> — source is tentatively selected, but publication terms are not yet finalized;</li><li><code>In Progress</code> — copy is being drafted or reviewed with platform administrators;</li><li><code>Published</code> — content is live on the target site with an active tracking link;</li><li><code>Completed</code> — promotion period concluded, with performance captured in analytics.</li></ul><h3 id="deterministic-link-injection" tabindex="-1">Deterministic Link Injection <a class="header-anchor" href="#deterministic-link-injection" aria-label="Permalink to &quot;Deterministic Link Injection&quot;">​</a></h3>',60)),t("p",null,[e[2]||(e[2]=a("When drafting promotional content using AI, OmniCraft ERP enforces an unbreakable engineering invariant: the language model generates strictly placeholder tokens ",-1)),t("code",null,n(i.CAMPAIGN_LINK),1),e[3]||(e[3]=a(" and ",-1)),t("code",null,n(i.PRODUCT_NAME),1),e[4]||(e[4]=a(".",-1))]),e[6]||(e[6]=o('<p>The actual target URL containing your affiliate identifier and channel parameters is injected programmatically by application code right before rendering. The neural model is physically incapable of distorting or losing tracking tokens.</p><h3 id="next-step-automation" tabindex="-1">&quot;Next Step&quot; Automation <a class="header-anchor" href="#next-step-automation" aria-label="Permalink to &quot;&quot;Next Step&quot; Automation&quot;">​</a></h3><p>Upon setting an item to <code>Published</code>, the software schedules future operational checkpoints:</p><ol><li><strong>At 3 Days:</strong> reminder notification to check initial clicks and sign-ups in Analytics;</li><li><strong>Post-Cooldown:</strong> notification indicating the channel cooldown has expired, allowing safe follow-up posting without risking community moderation penalties.</li></ol><hr><h2 id="_4-analytics-tab-performance-funnels-and-report-exports" tabindex="-1">4. &quot;Analytics&quot; Tab: Performance, Funnels, and Report Exports <a class="header-anchor" href="#_4-analytics-tab-performance-funnels-and-report-exports" aria-label="Permalink to &quot;4. &quot;Analytics&quot; Tab: Performance, Funnels, and Report Exports&quot;">​</a></h2><p>Marketing without accurate figures is an exercise in guesswork. The <strong>&quot;Analytics&quot;</strong> tab delivers an unvarnished view of the return on every dollar and hour invested.</p><table class="craft-matrix-table" style="text-align:center;"><thead><tr><th style="width:33%;text-align:center;">Link Clicks</th><th style="width:33%;text-align:center;">Sign-ups</th><th style="width:34%;text-align:center;">Completed Sales</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>4,820</strong></td><td style="text-align:center;"><strong>380</strong></td><td style="text-align:center;"><strong>48</strong></td></tr><tr><td style="text-align:center;"><strong>Affiliate Revenue:</strong><br><span style="color:#10b981;font-weight:600;">$ 426.00</span></td><td style="text-align:center;"><strong>Ad Spend:</strong><br>$ 85.00</td><td style="text-align:center;"><strong>Acquisition Cost:</strong><br>$ 1.77</td></tr></tbody></table><h3 id="_7-specialized-analytical-perspectives" tabindex="-1">7 Specialized Analytical Perspectives <a class="header-anchor" href="#_7-specialized-analytical-perspectives" aria-label="Permalink to &quot;7 Specialized Analytical Perspectives&quot;">​</a></h3><p>A dedicated selector at the top of the screen provides multiple analytical views:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Report View</th><th style="text-align:left;">What It Examines</th><th style="text-align:left;">Workshop Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Campaign Funnels</strong></td><td style="text-align:left;">Step-by-step conversion: Channels ➔ Clicks ➔ Sign-ups ➔ Sales ➔ Revenue with stage conversion rates.</td><td style="text-align:left;">Pinpoints drop-off points: whether friction occurs on link clicks or during checkout.</td></tr><tr><td style="text-align:left;"><strong>Channel Comparison</strong></td><td style="text-align:left;">Master table across &quot;Channel × Campaign&quot; pairs: placement type, budget, clicks, sales, and total revenue.</td><td style="text-align:left;">Identifies your most productive avenues and eliminates unprofitable spend.</td></tr><tr><td style="text-align:left;"><strong>Channel Types Breakdown</strong></td><td style="text-align:left;">Aggregated results by format: communities, articles, forums, video, direct advertising.</td><td style="text-align:left;">Identifies which communication style resonates best with your trade audience.</td></tr><tr><td style="text-align:left;"><strong>Tag Aggregation</strong></td><td style="text-align:left;">Metrics grouped by thematic tags (e.g., <em>&quot;leather&quot;</em>, <em>&quot;carpentry&quot;</em>, <em>&quot;clearance&quot;</em>).</td><td style="text-align:left;">Evaluates the performance of specific product collections or campaigns.</td></tr><tr><td style="text-align:left;"><strong>Paid Channel Economics</strong></td><td style="text-align:left;">Detailed cost per click, cost per acquisition, customer acquisition cost, and net return on spend.</td><td style="text-align:left;">Protects working capital by measuring whether paid traffic generates net profits.</td></tr><tr><td style="text-align:left;"><strong>Timeline Dynamics</strong></td><td style="text-align:left;">Daily distribution of clicks and sales across selected windows (7 days, 30 days, all time).</td><td style="text-align:left;">Measures post decay rates and helps calibrate future posting intervals.</td></tr><tr><td style="text-align:left;"><strong>Target Pages Summary</strong></td><td style="text-align:left;">Conversion comparison across landing pages (Home, Cost Calculator, Blog, Demo).</td><td style="text-align:left;">Demonstrates which site destinations convert visitors into paying clients most effectively.</td></tr></tbody></table><h3 id="key-economic-formulas" tabindex="-1">Key Economic Formulas <a class="header-anchor" href="#key-economic-formulas" aria-label="Permalink to &quot;Key Economic Formulas&quot;">​</a></h3><p>All analytical metrics are computed via transparent mathematical models:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Marketing Economics</span><div class="formula-heading">Channel Efficiency Formulas</div></div><div class="formula-equation-box"><div class="math-calc-stack"><div class="math-calc-row"><span class="math-calc-label">Conversion Rate (CR):</span><span class="math-calc-expr">(Completed Sales ÷ Link Clicks) × 100%</span></div><div class="math-calc-row"><span class="math-calc-label">Customer Acquisition Cost (CAC):</span><span class="math-calc-expr">Total Ad Spend ÷ Completed Sales</span></div><div class="math-calc-row"><span class="math-calc-label">Net Marketing ROI:</span><span class="math-calc-expr">((Attributed Revenue − Ad Spend) ÷ Ad Spend) × 100%</span></div></div></div><div class="formula-card-bottom"><p>All metrics are computed automatically from link tracking logs and recorded expenses.</p></div></div><div class="info custom-block"><p class="custom-block-title">Real Workshop Economics</p><p>If $ 30.00 was invested into an organic leathercraft community sponsorship yielding 200 clicks and 6 sales with an affiliate return of $ 48.00, the customer acquisition cost stands at $ 5.00 per client, delivering a 60% net return on marketing capital.</p></div><h3 id="report-export-and-offline-performance" tabindex="-1">Report Export and Offline Performance <a class="header-anchor" href="#report-export-and-offline-performance" aria-label="Permalink to &quot;Report Export and Offline Performance&quot;">​</a></h3><ul><li><strong>&quot;Export to CSV&quot; Button:</strong> exports structured tables encoded with UTF-8 BOM, ensuring seamless display in spreadsheet editors (Excel, Numbers, LibreOffice);</li><li><strong>&quot;Copy Report&quot; Button:</strong> copies formatted tab-separated text directly to your clipboard for quick messaging or project logs;</li><li><strong>Offline Independence:</strong> if network access drops, the module constructs all analytical views from locally stored metric snapshots with a subtle offline status indicator.</li></ul><hr><h2 id="_5-autonomous-digital-assistants-and-model-context-protocol" tabindex="-1">5. Autonomous Digital Assistants and Model Context Protocol <a class="header-anchor" href="#_5-autonomous-digital-assistants-and-model-context-protocol" aria-label="Permalink to &quot;5. Autonomous Digital Assistants and Model Context Protocol&quot;">​</a></h2><p>The Ambassador module is built for modern automation workflows, featuring out-of-the-box support for the open <strong>Model Context Protocol (MCP)</strong>.</p><p>This enables developers and technical craftsmen to connect local autonomous agents (e.g., inside Cursor, Antigravity, or Claude Desktop) directly to marketing operations:</p><ul><li><strong>Sandboxed Tool Registry:</strong> assistants interact via controlled API endpoints: <ul><li><code>list_campaigns</code> — retrieve active campaign registries;</li><li><code>get_stats</code> — query real-time performance metrics;</li><li><code>create_link</code> — programmatically generate tracking links;</li><li><code>generate_content</code> — request platform-specific copy drafts;</li><li><code>mark_published</code> — confirm live publication status;</li><li><code>export_task</code> — export full task context payloads.</li></ul></li><li><strong>Autonomy Levels and Human-in-the-Loop Safeguards:</strong><ul><li><em>Draft:</em> the assistant only drafts text variants and awaits human approval;</li><li><em>Semi-Auto:</em> automated posting that pauses immediately when CAPTCHA challenges or two-factor verifications appear;</li><li><em>Autopilot:</em> strictly limited to explicitly trusted internal channels.</li></ul></li><li><strong>Audit Logging:</strong> every tool execution is permanently captured in an audit table along with response times and submitted parameters.</li></ul><hr><h2 id="_6-affiliate-program-fair-economics-and-balance-usage" tabindex="-1">6. Affiliate Program: Fair Economics and Balance Usage <a class="header-anchor" href="#_6-affiliate-program-fair-economics-and-balance-usage" aria-label="Permalink to &quot;6. Affiliate Program: Fair Economics and Balance Usage&quot;">​</a></h2><p>The OmniCraft ERP affiliate program is built on mutual respect and long-term partnership.</p><h3 id="lifetime-referral-attribution" tabindex="-1">Lifetime Referral Attribution <a class="header-anchor" href="#lifetime-referral-attribution" aria-label="Permalink to &quot;Lifetime Referral Attribution&quot;">​</a></h3><p>When a colleague signs up through your link or scans the QR code from a sales receipt, the billing platform <strong>permanently binds that user to your partner profile</strong>:</p><ul><li>You earn commissions not just on their initial purchase, but on all future subscription renewals;</li><li>If the referred artisan purchases specialized trade extensions from the Marketplace, you receive commissions on those transactions as well;</li><li>Commissions accrue in real currency directly within your in-app balance.</li></ul><h3 id="utilizing-accumulated-earnings" tabindex="-1">Utilizing Accumulated Earnings <a class="header-anchor" href="#utilizing-accumulated-earnings" aria-label="Permalink to &quot;Utilizing Accumulated Earnings&quot;">​</a></h3><p>Your affiliate balance never expires. You retain complete freedom over how to allocate earnings:</p><table class="craft-matrix-table"><thead><tr><th style="width:40%;">Balance Usage Option</th><th style="width:60%;">Redemption Mechanism &amp; Terms</th></tr></thead><tbody><tr><td><strong>Bank Account Payout</strong></td><td>Direct wire transfer to bank accounts (minimum withdrawal $ 15.00).</td></tr><tr><td><strong>Subscription Renewal</strong></td><td>Apply bonus balance toward extending an active Standard subscription.</td></tr><tr><td><strong>Perpetual PRO Upgrade</strong></td><td>Unlock full lifetime multi-workspace access with zero out-of-pocket spend.</td></tr><tr><td><strong>Marketplace Extensions</strong></td><td>Acquire specialized craft tools and design templates using accumulated earnings.</td></tr></tbody></table><hr><h2 id="workshop-frequently-asked-questions" tabindex="-1">Workshop Frequently Asked Questions <a class="header-anchor" href="#workshop-frequently-asked-questions" aria-label="Permalink to &quot;Workshop Frequently Asked Questions&quot;">​</a></h2><h3 id="is-an-external-ai-api-key-mandatory-to-use-the-module" tabindex="-1">Is an external AI API key mandatory to use the module? <a class="header-anchor" href="#is-an-external-ai-api-key-mandatory-to-use-the-module" aria-label="Permalink to &quot;Is an external AI API key mandatory to use the module?&quot;">​</a></h3><p>No, it is entirely optional. The module is architected so that all primary workflows — manual link building, source directory management, ad spend tracking, receipt QR codes, conversion funnels, and analytics — function completely without external neural models. AI serves strictly as an optional workflow accelerator.</p><h3 id="how-are-commissions-credited-if-a-user-visits-the-link-but-buys-weeks-later" tabindex="-1">How are commissions credited if a user visits the link but buys weeks later? <a class="header-anchor" href="#how-are-commissions-credited-if-a-user-visits-the-link-but-buys-weeks-later" aria-label="Permalink to &quot;How are commissions credited if a user visits the link but buys weeks later?&quot;">​</a></h3><p>When a visitor arrives through your link, their browser receives an attribution cookie. When that artisan eventually purchases a license weeks later, the billing server connects the transaction to your referral code and credits your balance.</p><h3 id="what-happens-to-links-and-metrics-when-switching-or-archiving-workspaces" tabindex="-1">What happens to links and metrics when switching or archiving workspaces? <a class="header-anchor" href="#what-happens-to-links-and-metrics-when-switching-or-archiving-workspaces" aria-label="Permalink to &quot;What happens to links and metrics when switching or archiving workspaces?&quot;">​</a></h3><p>Nothing is lost. The Ambassador module is a cross-cutting global tool. Its data repository is isolated from individual trade workspaces. You can switch industries, clear test orders, or create new workshops — all tracking links, campaign archives, and earned balances remain intact.</p><h3 id="how-do-i-prevent-spam-complaints-when-sharing-links-on-community-forums" tabindex="-1">How do I prevent spam complaints when sharing links on community forums? <a class="header-anchor" href="#how-do-i-prevent-spam-complaints-when-sharing-links-on-community-forums" aria-label="Permalink to &quot;How do I prevent spam complaints when sharing links on community forums?&quot;">​</a></h3><p>The core principle of ethical marketing is providing genuine utility. Share links only in the context of solving a fellow artisan&#39;s concrete question (such as sharing a completed recipe cost breakdown or a pattern allowance guide). In every channel record, maintain reasonable cooldown periods and heed the &quot;Next Step&quot; scheduling reminders.</p>',41))])}const w=s(p,[["render",g]]);export{v as __pageData,w as default};
